import type { OptionalNullables } from './db.js';

export const GOAL_STATUSES = ['ACTIVE', 'ON_HOLD', 'COMPLETED', 'ARCHIVED'] as const;
export type GoalStatus = typeof GOAL_STATUSES[number];

export interface Goal {
    id: string;
    parent_id: string | null;
    title: string;
    description: string | null;
    status: GoalStatus;
    created_at: string;
    updated_at: string;
    sub_goals?: Goal[];
}

export type NewGoal = OptionalNullables<Omit<Goal, 'id' | 'created_at' | 'updated_at'>>;
