import type { DailySteps, NewDailySteps } from '../types/health.js';
import type { DbDriver } from '../types/db.js';
import { NOOP_LOGGER, type RepoLogger } from '../types/logger.js';
import { nowTimestamp } from '../utils/timestamp.js';

export interface DailyStepsRepositoryOptions {
    log?: RepoLogger;
}

export function createDailyStepsRepository(driver: DbDriver, options: DailyStepsRepositoryOptions = {}) {
    const log = options.log ?? NOOP_LOGGER;
    const repository = {
        async getByDateRange(from: string, to: string): Promise<DailySteps[]> {
            log.debug('dailySteps.getByDateRange', { from, to });
            return driver.query<DailySteps>(
                'SELECT * FROM daily_steps WHERE date >= ? AND date <= ? ORDER BY date DESC',
                from,
                to,
            );
        },

        /** Upsert keyed by `date` — a re-sync overwrites the day's total. */
        async upsert(payload: NewDailySteps): Promise<DailySteps> {
            log.debug('dailySteps.upsert', { date: payload.date, steps: payload.steps });
            await driver.execute(
                `INSERT INTO daily_steps (date, steps, source) VALUES (?, ?, ?)
                ON CONFLICT(date) DO UPDATE SET
                    steps      = excluded.steps,
                    source     = excluded.source,
                    updated_at = ?`,
                payload.date,
                payload.steps,
                payload.source,
                nowTimestamp(),
            );
            return driver.queryOne<DailySteps>('SELECT * FROM daily_steps WHERE date = ?', [payload.date], {
                notFound: () => new Error(`Failed to load upserted daily_steps row: ${payload.date}`),
            });
        },
    };

    return repository;
}

export type DailyStepsRepository = ReturnType<typeof createDailyStepsRepository>;
