/**
 * Story 281 — one live instance per browser, enforced rather than survived.
 *
 * Two windows on one OPFS file is not a state this app can be safe in. The
 * local DB is opened through `sqlite3.oo1.OpfsDb`, and SQLite's own file
 * locking does not span browsing contexts: each window's worker is an
 * independent SQLite instance with its own page cache and no mutual exclusion.
 * Story 214's `withExclusiveDbLock` serializes the operations the app knows are
 * mutating (`load-snapshot`, `schema-init`, `wipe`), but the ordinary
 * `openDatabase()` connections other windows already hold never take that lock,
 * so an import can still land under a live foreign page cache. The result was
 * `SQLITE_CORRUPT: malformed database schema (embeddinggemma)` — a *data* value
 * where a schema object belongs, i.e. a data page parsed as a schema page:
 * physical corruption of the user's replica, measured at roughly 1 in 27
 * concurrent boots.
 *
 * The owner's call (2026-08-08) is that concurrent windows are **not a
 * supported configuration** — one instance per browser is a fine limit, and it
 * only ever comes up when debugging. So this does not make concurrency safe; it
 * makes concurrency impossible, which is the only version of the guarantee that
 * can actually be proven. A blocked window never opens the file at all.
 *
 * **Web Locks, held for the document's lifetime.** The live instance holds
 * `motivation-app-instance` and never releases it; the browser drops it when
 * the context dies. That is the whole reason to prefer a lock over a
 * localStorage heartbeat: there is no stale entry to expire, no clock to trust,
 * and a crashed window frees the slot immediately. The API is already the
 * app's precedent for cross-context coordination (story 214's DB lock, story
 * 268's queue-drain lock).
 *
 * **Takeover is `steal: true`**, which the Web Locks API provides for exactly
 * this case: it forcibly releases the current holder, whose held request then
 * rejects with `AbortError`. No BroadcastChannel handshake, and no dependency
 * on the loser being responsive.
 */

export const INSTANCE_LOCK_NAME = 'motivation-app-instance';

export interface ClaimInstanceOptions {
    /** Injectable for tests; defaults to `navigator.locks`. */
    locks?: LockManager | undefined;
    /** `true` to take the lock away from the current holder (the takeover button). */
    steal?: boolean;
    /**
     * Called when this window's held lock is stolen by another window. Fires
     * only after a successful claim, never on a failed one.
     */
    onLost?: () => void;
}

/**
 * Try to become the live instance. Resolves `true` when this document may use
 * the local database, `false` when another window already holds it.
 *
 * Degrades to `true` where Web Locks is absent (jsdom, and any browser without
 * the API): an undetectable second window is the pre-281 status quo, and
 * bricking the app on a missing platform feature would be a worse failure than
 * the one this guards against.
 */
export async function claimInstance(options: ClaimInstanceOptions = {}): Promise<boolean> {
    const locks = options.locks ?? (typeof navigator === 'undefined' ? undefined : navigator.locks);
    if (!locks) {
        console.warn('[instance] Web Locks unavailable — cannot detect a second window; proceeding unguarded');
        return true;
    }

    return new Promise<boolean>((resolve, reject) => {
        let claimed = false;
        locks.request(
            INSTANCE_LOCK_NAME,
            options.steal ? { mode: 'exclusive', steal: true } : { mode: 'exclusive', ifAvailable: true },
            (lock) => {
                if (!lock) {
                    console.log('[instance] claim refused — another window is already live');
                    resolve(false);
                    return;
                }
                claimed = true;
                console.log(`[instance] claim granted (steal=${options.steal === true})`);
                resolve(true);
                // Never resolves: the lock is held until this context dies.
                return new Promise<void>(() => {});
            },
        ).catch((error: unknown) => {
            // A `steal: true` from another window aborts the held request above.
            // Before the claim, the same rejection is a real failure.
            if (claimed) {
                console.warn('[instance] this window is no longer the live instance — another window took over');
                options.onLost?.();
                return;
            }
            reject(error);
        });
    });
}

export interface InstanceBlockedOptions {
    doc?: Document;
    /** What the single button does. Label is chosen to match. */
    action: 'take-over' | 'reload';
    onAction: () => void;
}

/**
 * The blocked screen: deliberately raw text, no styling beyond what it takes to
 * be readable. Nothing here is a product surface — it is the app saying it will
 * not run twice.
 *
 * It **hides** the existing body children rather than replacing them, and
 * returns a dismiss function, because a takeover continues booting in place:
 * `#route-outlet` has to survive, and `replaceChildren` (which `boot-failure.ts`
 * can afford, being terminal) would destroy it.
 *
 * Colours are inline for the same reason `boot-failure.ts` sets them: this may
 * render before any component stylesheet has been adopted, and stories 285/286
 * are a long argument against assuming an inherited colour is legible.
 */
export function renderInstanceBlocked({ doc = document, action, onAction }: InstanceBlockedOptions): () => void {
    const hidden = [...doc.body.children].filter((child): child is HTMLElement =>
        child instanceof HTMLElement && !child.hidden);
    for (const child of hidden) child.hidden = true;

    const notice = doc.createElement('div');
    notice.id = 'instance-blocked';
    notice.style.color = '#eee';
    notice.style.padding = '1rem';

    const heading = doc.createElement('h1');
    heading.textContent = action === 'take-over'
        ? 'Already open in another window'
        : 'Another window took over';

    const body = doc.createElement('p');
    body.textContent = action === 'take-over'
        ? 'This app keeps one local database per browser, and two windows sharing it can corrupt it. '
            + 'Close the other window, or take over here — the other window will drop to this same screen.'
        // The loss case is past tense and this document's DB access is already
        // revoked, so the only way back is a fresh one. A user gesture always
        // navigates, which is why this is a button and not an automatic reload.
        : 'Another window took the local database, so this one stopped using it. Reload to use it here '
            + 'instead — the other window will then drop to this same screen.';

    const button = doc.createElement('button');
    button.id = action === 'take-over' ? 'instance-take-over' : 'instance-reload';
    button.type = 'button';
    button.textContent = action === 'take-over' ? 'Use this window' : 'Reload';
    button.addEventListener('click', () => onAction());

    notice.append(heading, body, button);
    doc.body.appendChild(notice);

    return () => {
        notice.remove();
        for (const child of hidden) child.hidden = false;
    };
}
