import {
    createCardioDetailsRepository,
    createConsumptionRepository,
    createDailyStepsRepository,
    createWeightEntriesRepository,
    createExerciseRepository,
    createFoodItemRepository,
    createGoalRepository,
    createHealthRepository,
    createMealRepository,
    createSocialRepository,
    createVietnameseRepository,
    createWorkoutRepository,
    createWorkoutTemplateRepository,
    GOAL_ROUTE_KEYS,
    HEALTH_ROUTE_KEYS,
    SOCIAL_ROUTE_KEYS,
    VIETNAMESE_ROUTE_KEYS,
    type GoalRouteKey,
    type HealthRouteKey,
    type SocialRouteKey,
    type VietnameseRouteKey,
    type ApiResponse,
    type RouteContext,
    BadRequestError,
    errorResponse,
} from '@motivation/shared';
import { DbService } from '../../db/db.service.js';
import { createComponentLogger, createRepoLogger } from '../../utils/component-logger.js';
import type { OfflineRequestEnvelope } from '../sw-messages.js';

const log = createComponentLogger('offline');
import {
    GoalOfflineRoutes,
    HealthOfflineRoutes,
    SocialOfflineRoutes,
    VietnameseOfflineRoutes,
} from './offline-routes.js';

export interface OfflineApiRouterOptions {
    onUnhandledRequest?: (request: RouteContext & { method: string; path: string }) => ApiResponse;
}

/**
 * The envelope carried a body the router cannot read. Story 264: this used to
 * escape `toRouteContext` as a bare `SyntaxError` and land in the generic catch
 * as a **503** whose `error` was the raw V8 parse complaint — a multipart image
 * upload reported to the user as a service outage
 * ("No number after minus sign in JSON at position 1"). It is a request the
 * offline router cannot serve, not a failure of the local stack, so it is
 * classified 400 (a `BadRequestError`, story 386) and says which request and why.
 */
class UnreadableRequestBodyError extends BadRequestError {
    constructor(method: string, path: string, detail: string) {
        super(`Offline router cannot read the body of ${method} ${path}: it is not JSON (${detail}) — this request requires the network`);
        this.name = 'UnreadableRequestBodyError';
    }
}

/**
 * Decode one path parameter, because Express decodes its params and the
 * services encode every segment they send: an id needing escapes would
 * otherwise reach the repositories escaped offline and bare online, so the same
 * read would answer differently on either side of the sync boundary.
 *
 * A malformed escape falls back to the raw segment rather than throwing. Route
 * matching runs in a loop over every key, so a `URIError` here would abort
 * dispatch for the whole request instead of letting the repository answer "no
 * such id" — which is the truthful answer for a segment that cannot be decoded,
 * and is what this did before it decoded at all.
 */
export function decodeParam(segment: string): string {
    if (!segment.includes('%')) return segment;
    try {
        return decodeURIComponent(segment);
    } catch {
        return segment;
    }
}

export class OfflineApiRouter {
    private readonly handleMessageBound = this.handleMessage.bind(this);
    private offlineRoutes: HealthOfflineRoutes | null = null;
    private goalOfflineRoutes: GoalOfflineRoutes | null = null;
    private socialOfflineRoutes: SocialOfflineRoutes | null = null;
    private vietnameseOfflineRoutes: VietnameseOfflineRoutes | null = null;

    constructor(private readonly options: OfflineApiRouterOptions = {}) {}

    start(): void {
        navigator.serviceWorker.addEventListener('message', this.handleMessageBound as unknown as EventListener);
    }

    stop(): void {
        navigator.serviceWorker.removeEventListener('message', this.handleMessageBound as unknown as EventListener);
    }

    private async handleMessage(event: MessageEvent<Partial<OfflineRequestEnvelope>>): Promise<void> {
        // If it's not an offline-request, it's not for us, so ignore it silently.
        if (event.data?.type !== 'offline-request') {
            return;
        }

        // If it is an offline-request, it MUST have a reply port to send the response back.
        if (!event.ports?.[0]) {
            console.warn('Ignoring malformed offline router message', {
                hasData: true,
                dataType: event.data.type,
                hasPort: false,
            });
            return;
        }

        const envelope = event.data as OfflineRequestEnvelope;
        const port = event.ports[0];
        try {
            const request = this.toRouteContext(envelope.request);
            const response = await this.route(request);
            port.postMessage(response);
        } catch (error) {
            // Story 333/386: the server's mapping, so a typed error means the same
            // status on both sides of the sync boundary and 503 keeps meaning only
            // "requires the network" (story 296). A programming error is a 500.
            port.postMessage(errorResponse(error));
        }
    }

    private toRouteContext(request: OfflineRequestEnvelope['request']): RouteContext & { method: string; path: string } {
        const parsedUrl = new URL(request.url, window.location.origin);
        let body: unknown = undefined;

        if (typeof request.body === 'string' && request.body.trim().length > 0) {
            try {
                body = JSON.parse(request.body);
            } catch (error) {
                throw new UnreadableRequestBodyError(
                    request.method,
                    parsedUrl.pathname,
                    error instanceof Error ? error.message : 'unparseable',
                );
            }
        }

        return {
            method: request.method,
            path: parsedUrl.pathname,
            params: {},
            query: parsedUrl.searchParams,
            body,
        };
    }

    private async route(request: RouteContext & { method: string; path: string }): Promise<ApiResponse> {
        const goalResponse = await this.routeGoals(request);
        if (goalResponse) {
            return goalResponse;
        }

        const healthResponse = await this.routeHealth(request);
        if (healthResponse) {
            return healthResponse;
        }

        const socialResponse = await this.routeSocial(request);
        if (socialResponse) {
            return socialResponse;
        }

        const vietnameseResponse = await this.routeVietnamese(request);
        if (vietnameseResponse) {
            return vietnameseResponse;
        }

        if (this.options.onUnhandledRequest) {
            return this.options.onUnhandledRequest(request);
        }

        // Story 296: this used to answer **404**, which says "the server looked
        // and there is no such route". The truth is the opposite — the route
        // exists server-side and we could not reach it, because reaching the
        // offline router at all means the network fetch already failed. Callers
        // read that 404 literally: `subscribePush` reported
        // `Failed to fetch VAPID key: HTTP 404` for a route the server answers
        // 200 all day, and `projects.service` carries a comment about the same
        // "misleading Offline route not found 404".
        //
        // 503 with the story-264 wording ("requires the network") says the one
        // thing that is actually true. 404 is left to mean what it should: a
        // `NotFoundError` from a route this router **does** own, which is why
        // `findActivity` / `findFoodItem`'s `status === 404 → null` still works.
        log.warn(`${request.method} ${request.path} requires the network: the offline router does not serve this route.`);

        return {
            status: 503,
            headers: { 'Content-Type': 'application/json' },
            body: { error: `${request.method} ${request.path} requires the network: the offline router does not serve this route` },
        };
    }

    private async routeGoals(request: RouteContext & { method: string; path: string }): Promise<ApiResponse | null> {
        const relativePath = this.toSectionPath(request.path, '/api/goals');
        if (!relativePath) {
            return null;
        }

        for (const key of GOAL_ROUTE_KEYS) {
            const match = this.matchRoute(key, request.method, relativePath);
            if (!match) {
                continue;
            }

            const routes = this.getGoalOfflineRoutes();
            return routes[key]({
                params: match.params,
                query: request.query,
                body: request.body,
            });
        }

        return null;
    }

    private async routeHealth(request: RouteContext & { method: string; path: string }): Promise<ApiResponse | null> {
        const relativePath = this.toSectionPath(request.path, '/api/sections/health');
        if (!relativePath) {
            return null;
        }

        for (const key of HEALTH_ROUTE_KEYS) {
            const match = this.matchRoute(key, request.method, relativePath);
            if (!match) {
                continue;
            }

            const routes = this.getOfflineRoutes();
            return await routes[key]({
                params: match.params,
                query: request.query,
                body: request.body,
            });
        }

        return null;
    }

    private async routeSocial(request: RouteContext & { method: string; path: string }): Promise<ApiResponse | null> {
        const relativePath = this.toSectionPath(request.path, '/api/sections/social');
        if (!relativePath) {
            return null;
        }

        for (const key of SOCIAL_ROUTE_KEYS) {
            const match = this.matchRoute(key, request.method, relativePath);
            if (!match) {
                continue;
            }

            const routes = this.getSocialOfflineRoutes();
            return routes[key]({
                params: match.params,
                query: request.query,
                body: request.body,
            });
        }

        return null;
    }

    private async routeVietnamese(request: RouteContext & { method: string; path: string }): Promise<ApiResponse | null> {
        const relativePath = this.toSectionPath(request.path, '/api/sections/vietnamese');
        if (!relativePath) {
            return null;
        }

        for (const key of VIETNAMESE_ROUTE_KEYS) {
            const match = this.matchRoute(key, request.method, relativePath);
            if (!match) {
                continue;
            }

            const routes = this.getVietnameseOfflineRoutes();
            return routes[key]({
                params: match.params,
                query: request.query,
                body: request.body,
            });
        }

        return null;
    }

    private getGoalOfflineRoutes(): GoalOfflineRoutes {
        if (this.goalOfflineRoutes) {
            return this.goalOfflineRoutes;
        }

        this.goalOfflineRoutes = new GoalOfflineRoutes(
            createGoalRepository(DbService.getInstance().driver, { log: createRepoLogger('repo:goals') }),
        );
        return this.goalOfflineRoutes;
    }

    private getOfflineRoutes(): HealthOfflineRoutes {
        if (this.offlineRoutes) {
            return this.offlineRoutes;
        }

        const driver = DbService.getInstance().driver;
        this.offlineRoutes = new HealthOfflineRoutes({
            activities: createHealthRepository(driver, { log: createRepoLogger('repo:health') }),
            foodItems: createFoodItemRepository(driver, { log: createRepoLogger('repo:food-items') }),
            consumption: createConsumptionRepository(driver, { log: createRepoLogger('repo:consumption') }),
            weight: createWeightEntriesRepository(driver, { log: createRepoLogger('repo:weight') }),
            dailySteps: createDailyStepsRepository(driver, { log: createRepoLogger('repo:daily-steps') }),
            meals: createMealRepository(driver, { log: createRepoLogger('repo:meals') }),
            exercises: createExerciseRepository(driver, { log: createRepoLogger('repo:exercises') }),
            cardioDetails: createCardioDetailsRepository(driver, { log: createRepoLogger('repo:cardio-details') }),
            workoutTemplates: createWorkoutTemplateRepository(driver, { log: createRepoLogger('repo:workout-templates') }),
            workouts: createWorkoutRepository(driver, { log: createRepoLogger('repo:workouts') }),
        });
        return this.offlineRoutes;
    }

    private getSocialOfflineRoutes(): SocialOfflineRoutes {
        if (this.socialOfflineRoutes) {
            return this.socialOfflineRoutes;
        }

        this.socialOfflineRoutes = new SocialOfflineRoutes(
            createSocialRepository(DbService.getInstance().driver, { log: createRepoLogger('repo:social') }),
        );
        return this.socialOfflineRoutes;
    }

    private getVietnameseOfflineRoutes(): VietnameseOfflineRoutes {
        if (this.vietnameseOfflineRoutes) {
            return this.vietnameseOfflineRoutes;
        }

        this.vietnameseOfflineRoutes = new VietnameseOfflineRoutes(
            createVietnameseRepository(DbService.getInstance().driver, { log: createRepoLogger('repo:vietnamese') }),
        );
        return this.vietnameseOfflineRoutes;
    }

    private matchRoute(
        key: HealthRouteKey | GoalRouteKey | SocialRouteKey | VietnameseRouteKey,
        requestMethod: string,
        requestPath: string,
    ): { params: Record<string, string> } | null {
        const [method, templatePath] = key.split(' ') as [string, string];
        if (method !== requestMethod.toUpperCase()) {
            return null;
        }

        const templateParts = templatePath.split('/').filter(Boolean);
        const requestParts = requestPath.split('/').filter(Boolean);
        if (templateParts.length !== requestParts.length) {
            return null;
        }

        const params: Record<string, string> = {};
        for (let i = 0; i < templateParts.length; i += 1) {
            const templatePart = templateParts[i];
            const requestPart = requestParts[i];
            if (templatePart.startsWith(':')) {
                params[templatePart.slice(1)] = decodeParam(requestPart);
                continue;
            }
            if (templatePart !== requestPart) {
                return null;
            }
        }

        return { params };
    }

    private toSectionPath(path: string, prefix: string): string | null {
        if (!path.startsWith(prefix)) {
            return null;
        }

        const relative = path.slice(prefix.length);
        return relative.length > 0 ? relative : '/';
    }
}
