import { DbService } from './db.service.js';
import { downloadAndLoadSnapshot } from './db-snapshot.service.js';
import { isApiReachable } from './api-reachability.js';
import { createComponentLogger } from '../utils/component-logger.js';

const log = createComponentLogger('app');

/**
 * Local-DB bootstrap decision, extracted from app.ts for unit-testability
 * (story 215). The orchestration around it — OfflineApiRouter, the DbService
 * singleton, markBootstrapComplete — stays in app.ts; this owns only the
 * exists → import-with-retry → empty-schema-fallback logic and its outcome.
 *
 * The 2026-06-12 wedge began here: a single transient import failure fell
 * straight to an empty schema and declared bootstrap done. Two corrections:
 * - **Retry** an online import failure a few times before giving up (a flaky
 *   link or a one-shot race resolves in milliseconds) — the "bounded retry
 *   window" that lets a failed first import still reach the snapshot.
 * - **Distinguish** a first boot that cannot reach the API (nothing to import —
 *   empty schema is correct and silent; story 267 made this an actual API probe
 *   rather than `navigator.onLine`) from an import that failed with the API
 *   reachable after retries (degraded: fall back to empty schema so the app runs online-first,
 *   but say so LOUDLY — the baseline-aware refreshIfStale guard heals it on the
 *   next trigger rather than wedging forever).
 */

export type BootstrapOutcome =
    | { result: 'existing' }
    | { result: 'snapshot' }
    | { result: 'empty-offline' }
    | { result: 'empty-failed'; error: string };

export interface BootstrapDeps {
    exists: () => Promise<boolean>;
    /** Resolves true when a snapshot was imported; throws on fetch/HTTP/import failure. */
    download: () => Promise<boolean>;
    initSchema: () => Promise<void>;
    /**
     * "Can we reach the API?" — NOT `navigator.onLine` (story 267). Production
     * wiring probes the API; may be async, and is awaited.
     */
    isOnline: () => boolean | Promise<boolean>;
    sleep: (ms: number) => Promise<void>;
    maxImportAttempts?: number;
}

const DEFAULT_BACKOFFS_MS = [300, 600];

/**
 * Story 266 — a timed-out `db-exists` is contention, not a verdict.
 *
 * Two document boots ~3 s apart (a fast back/forward, 2026-07-22 01:15) left
 * the outgoing document's worker holding the OPFS sync-access handle, so the
 * incoming document's probe hung out the driver's 30 s timeout and bootstrap
 * gave up — landing on a fallback that is a dead end in Isolated Mode. The
 * handle IS freed once the old document goes away (the manual reload 19 s later
 * probed `true` immediately), so re-probe within a bounded budget before any
 * fallback is chosen. Only *timeouts* are retried: `hasOpfsSnapshot()` already
 * answers `false` for a missing file and for a broken one (out loud, story
 * 360), so any other rejection here is a real defect and stays loud on the
 * first occurrence.
 */
const EXISTS_MAX_ATTEMPTS = 3;
const EXISTS_BACKOFFS_MS = [500, 1000];

const isTimeoutError = (err: unknown): boolean => err instanceof Error && /timed out/i.test(err.message);

async function probeExists(
    exists: () => Promise<boolean>,
    sleep: (ms: number) => Promise<void>,
): Promise<boolean> {
    let attempt = 0;
    for (;;) {
        attempt += 1;
        try {
            return await exists();
        } catch (err) {
            if (!isTimeoutError(err) || attempt >= EXISTS_MAX_ATTEMPTS) {
                throw err;
            }
            log.warn(`db-exists probe attempt ${attempt}/${EXISTS_MAX_ATTEMPTS} timed out (another document may still hold the OPFS handle); retrying:`, err);
            await sleep(EXISTS_BACKOFFS_MS[Math.min(attempt - 1, EXISTS_BACKOFFS_MS.length - 1)]);
        }
    }
}

export async function bootstrapLocalDatabase(deps: BootstrapDeps): Promise<BootstrapOutcome> {
    const { exists, download, initSchema, isOnline, sleep, maxImportAttempts = 3 } = deps;

    if (await probeExists(exists, sleep)) {
        return { result: 'existing' };
    }

    let lastError = 'snapshot not applied';
    for (let attempt = 1; attempt <= maxImportAttempts; attempt += 1) {
        try {
            if (await download()) {
                return { result: 'snapshot' };
            }
            // A non-apply (a requireNoPending refusal) — bootstrap passes none,
            // so this is not expected; treat as a soft failure and fall through.
        } catch (err) {
            // The API cannot be reached — genuinely offline, or (story 267) this
            // device has a network but no route to the LAN API. Either way there
            // is nothing to import, so an empty schema is the correct first-boot
            // state. Don't retry or escalate.
            if (!(await isOnline())) {
                await initSchema();
                return { result: 'empty-offline' };
            }
            lastError = err instanceof Error ? err.message : String(err);
            log.warn(`snapshot import attempt ${attempt}/${maxImportAttempts} failed (API reachable):`, err);
        }
        if (attempt < maxImportAttempts) {
            await sleep(DEFAULT_BACKOFFS_MS[Math.min(attempt - 1, DEFAULT_BACKOFFS_MS.length - 1)]);
        }
    }

    // Online but every attempt failed. Fall back to empty schema so the app
    // runs online-first (router + SW proxy already work); the baseline-aware
    // refreshIfStale guard (story 215) heals it on the next trigger once the
    // server recovers. Loud — this is a degraded state, not a normal one.
    log.error(`snapshot import failed after ${maxImportAttempts} attempts; falling back to empty schema (online-first, will self-heal):`, lastError);
    await initSchema();
    return { result: 'empty-failed', error: lastError };
}

/** Production wiring: bind the deps to the real DbService + snapshot download. */
export function bootstrapLocalDatabaseWithDefaults(dbService: DbService): Promise<BootstrapOutcome> {
    return bootstrapLocalDatabase({
        exists: () => dbService.exists(),
        download: () => downloadAndLoadSnapshot({ dbService }),
        initSchema: () => dbService.initSchema(),
        isOnline: () => isApiReachable(),
        sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
    });
}
