import type { RouteConfig } from '../../router.js';

export function agendaRoutes(): Record<string, RouteConfig> {
    return {
        '/agenda': {
            // Reached from the Extra screen's nav, not from home.
            parent: '/extra',
            render: async () => {
                await import('./agenda-screen/agenda-screen.component.js');
                return document.createElement('agenda-screen');
            },
        },
    };
}
