const log = createComponentLogger('app');

let offlineApiRouter: OfflineApiRouter | null = null;

/**
 * Story 221 — drain the async-estimate submit queue (a photo/text estimate
 * enqueued while offline). Lazily imported so it stays off the startup path.
 */
async function drainEstimateSubmits(reason: string): Promise<void> {
    try {
        const m = await import('./services/offline/estimate-submit-shipping.js');
        await m.shipPendingEstimateSubmits();
    } catch (err) {
        console.warn(`Estimate submit shipping (${reason}) failed:`, err);
    }
}

/**
 * Story 370: rows first, then photos. The image drain puts a photo on its food or meal (story
 * 362), and a meal created offline reaches the server only with the change push — so draining
 * both at once had the photo's PATCH beat its row there and wait for the next trigger.
 * Imported statically: a chunk fetched this late in boot 404s once a deploy has swapped the
 * service worker under the page.
 */
async function shipQueuedPhotos(reason: string): Promise<void> {
    try {
        await shipPendingImageUploads();
    } catch (err) {
        console.warn(`Image upload queue shipping (${reason}) failed:`, err);
    }
}


async function initializeLocalDatabase(): Promise<LocalDbBootstrapStatus> {
    log.debug('initializeLocalDatabase() START');
    try {
        if (!offlineApiRouter) {
            offlineApiRouter = new OfflineApiRouter();
            offlineApiRouter.start();
            log.debug('OfflineApiRouter started');
        }

        const dbService = DbService.getInstance();
        log.debug('Calling dbService.init()...');
        await dbService.init();
        log.debug('dbService.init() DONE');

        // Retry a failed online import before falling back; a genuinely-offline
        // first boot still lands on an empty schema silently. A degraded
        // (online-but-import-failed) fallback is loud and heals via the
        // baseline-aware refreshIfStale guard. Story 215.
        const outcome = await bootstrapLocalDatabaseWithDefaults(dbService);
        log.debug('initializeLocalDatabase() COMPLETE', outcome);
        document.documentElement.dataset.dbBootstrap = 'complete';
        // From here on, a missing _pending_changes table is a real defect
        // (recoverable via wipe+reload) rather than an in-flight bootstrap.
        // Gates the sync recovery path — story 190.
        DbService.getInstance().markBootstrapSucceeded();
        return 'succeeded';
    } catch (error) {
        // Story 266 — do NOT claim "continuing in online-first mode". This
        // device runs Isolated Mode against a LAN API, so when the local
        // replica is missing there is no second source for /api reads: every
        // one becomes `503 unable to route to local handler`. Say what actually
        // happened and what recovers it.
        console.error(
            'Local database initialization FAILED — there is no local replica this session, so every '
            + '/api read that cannot reach the server will fail (this is NOT an online-first fallback). '
            + 'Recover with a reload, or wipe local data and reload to re-download the snapshot.',
            error,
        );
        document.documentElement.dataset.dbBootstrap = 'failed';
        // Still settles every whenBootstrapComplete() waiter — nobody may hang
        // on a dead bootstrap — but as 'failed', so a missing table reads as a
        // recoverable state rather than a real defect (story 198's contract).
        DbService.getInstance().markBootstrapFailed();
        return 'failed';
    }
}

export async function startApp(): Promise<void> {
    // Story 232: react to a deploy taking over mid-session. Attach BEFORE
    // registering so the controllerchange from a new worker's skipWaiting()+
    // claim() can't fire before the listener exists. Inert on first install
    // (no controller yet) and in DEV (no SW) — see reloadOnServiceWorkerUpdate.
    reloadOnServiceWorkerUpdate();

    // ALWAYS attempt to register the service worker (it will return early in DEV mode).
    // This is required for offline caching to work in production!
    void registerServiceWorker().catch(err => {
        console.error('Service Worker registration failed:', err);
    });

    if (!window.crossOriginIsolated) {
        console.warn('Environment is not Cross-Origin Isolated. Halting boot until Service Worker injects headers and reloads.');
        document.body.textContent = 'Initializing Offline Storage... Please wait.';

        /*
         * Story 306 — whatever gates this reload must not be able to give up,
         * because everything the user ever sees is on the far side of it.
         *
         * This used to wait on `registerServiceWorker()`, which abandoned its
         * activation wait after 10 s and rejected; the rejection was caught into
         * `undefined` above and this branch returned without reloading. A first
         * install precaches ~120 assets, which on a weak radio is comfortably
         * more than 10 s — so the app sat on the line above, with no error and
         * no retry, until it was force-quit, while the worker activated moments
         * later with nobody listening.
         *
         * `navigator.serviceWorker.ready` has no timeout and no failure mode. It
         * resolves once a worker is active for this scope, which is exactly and
         * only the condition this reload needs: the reloaded document is then
         * controlled, so the worker can inject the COOP/COEP headers that
         * GitHub Pages does not send. Unreachable in DEV — Vite serves those
         * headers itself, so an isolated dev page never enters this branch.
         */
        void navigator.serviceWorker.ready.then(() => { window.location.reload(); });
        return; // Halt normal boot until reload
    }

    console.log('Motivation PWA Started (Isolated Mode)');

    // Observable boot state for the lifecycle e2e harness (story 212), same
    // pattern as story 200's data-saving-preferences: which build is running,
    // and (set by initializeLocalDatabase) whether the local DB came up.
    document.documentElement.dataset.buildStamp = BUILD_STAMP;

    /*
     * Story 281 — refuse to be the second window, before anything opens the DB.
     *
     * Two live instances on one OPFS file physically corrupt it (SQLite's own
     * file locking does not span browsing contexts), and concurrent windows are
     * explicitly not a supported configuration. This is placed AFTER the COI
     * halt — which reloads, and must keep doing so — and BEFORE the router and
     * `initializeLocalDatabase`, so a blocked window never constructs the DB
     * worker and therefore never opens the file. That is what makes the
     * guarantee provable rather than merely likely.
     */
    const live = await claimInstance({ onLost: onInstanceLost });
    if (!live) {
        showInstanceBlocked();
        return;
    }
    document.documentElement.dataset.appInstance = 'live';
    continueBoot();
}

/**
 * Story 281 — this window lost the lock to another window's takeover. Reload
 * rather than tearing down in place: it terminates the DB worker (releasing the
 * OPFS handle through the existing `pagehide` path) and re-enters the guard,
 * which now finds the lock held and lands here on the blocked screen. The
 * winner does NOT reload, so there is no race over the freed lock.
 */
function onInstanceLost(): void {
    // Revoke FIRST, synchronously: from this moment nothing in this document
    // can reach the file the other window now owns.
    DbService.getInstance().revokeForInstanceLoss();
    document.documentElement.dataset.appInstance = 'blocked';
    renderInstanceBlocked({ action: 'reload', onAction: () => window.location.reload() });
}

function showInstanceBlocked(): void {
    document.documentElement.dataset.appInstance = 'blocked';
    const dismiss = renderInstanceBlocked({
        action: 'take-over',
        onAction: () => {
            void claimInstance({ steal: true, onLost: onInstanceLost }).then(() => {
                dismiss();
                document.documentElement.dataset.appInstance = 'live';
                // Boots in place — see renderInstanceBlocked on why the DOM has
                // to survive rather than be replaced.
                continueBoot();
            });
        },
    });
}

function continueBoot(): void {
    // Single message bridge for everything the SW posts: snapshot-mark-dirty
    // (story 133 trigger 1), snapshot-refresh (trigger 4), notification-click
    // (existing). Exhaustive dispatch via the typed SwMessage union.
    attachSwMessageBridge(navigator.serviceWorker, {
        onSnapshotMarkDirty: () => markDirty(),
        onSnapshotRefresh: () => { void refreshIfStale(); },
        // Story 293: `arriveAt`, not a bare `navigate`. A notification tapped
        // while the app is open used to push its target onto whatever screen
        // happened to be showing, so back returned to an unrelated section.
        // This seeds the target's declared parent chain instead, so back climbs
        // out through the section the notification pointed into.
        onNotificationClick: ({ path }) => { void arriveAt(path); },
    });

    const outlet = document.getElementById('route-outlet')!;

    // Start the router immediately — it does NOT depend on the local DB.
    // Screens fetch through the SW proxy, which reaches the server when online
    // and only falls back to the local DB when offline. Gating the router
    // behind initializeLocalDatabase() meant a hung init (e.g.
    // navigator.storage.persist() on PWA resume — design_log #155) left this
    // outlet empty: an unrecoverable black screen. The local DB now initialises
    // in the background; the offline path returns a retryable 503 for the
    // sub-second window before it is ready, never a blank screen.
    startRouter({
        ...homeRoutes(),
        ...goalRoutes(),
        ...agendaRoutes(),
        ...healthRoutes(),
        ...aiRoutes(),
        ...vietnameseRoutes(),
        ...projectsRoutes(),
        ...extraRoutes(),
        ...statusScreenRoutes(),
    }, outlet);

    // Story 266: hand the OPFS sync-access handle back before this document
    // goes away. On a fast back/forward the outgoing document's worker kept it,
    // and the incoming document's `db-exists` hung out the driver's 30s timeout
    // behind it (2026-07-22 01:15). `pagehide` — not `beforeunload`, which is
    // unreliable on mobile and blocks bfcache — fires for back/forward
    // navigation, which is the logged trigger. Registered here rather than
    // inside initializeLocalDatabase so a document whose init is still in
    // flight (or already failed) still releases whatever it opened.
    window.addEventListener('pagehide', () => {
        void DbService.getInstance().releaseConnection().catch((error) => {
            log.warn('pagehide OPFS release failed:', error);
        });
    });

    // Route unhandled rejections to the active screen so the UI never
    // stays silently stuck when a catch is missing.
    window.addEventListener('unhandledrejection', (event) => {
        const screen = outlet.firstElementChild;
        if (screen && 'setError' in screen && typeof (screen as HTMLElement & { setError: unknown }).setError === 'function') {
            (screen as unknown as { setError(err: unknown): void }).setError(event.reason);
        }
    });

    void initializeLocalDatabase().then((status) => {
        if (status === 'failed') {
            // Story 266: every one of the follow-ups below reads the local
            // `settings` table. Firing them at a DB that never came up is what
            // produced the 01:15:49 unhandled `no such table: settings`
            // rejections — which the handler above then painted, raw, over the
            // active screen. The failure is already loud (console.error +
            // data-db-bootstrap="failed"), and a reload re-runs bootstrap with
            // the story-266 probe retry.
            log.warn('skipping local-DB-dependent startup work (timezone, health targets, push, snapshot refresh) — bootstrap failed');
            return;
        }

        // Story 280: every task below reads (and the timezone one writes) the
        // local `settings` table, and a bare `void` left its rejection to the
        // `unhandledrejection` listener above — which paints the raw SQLite error
        // over whatever screen is showing. That is the 01:15:49 symptom, and
        // story 266 only closed the bootstrap-FAILED half (skipped, above). A DB
        // can also go bad AFTER a healthy bootstrap: story 190's wipe+reload,
        // story 281's cross-window import replacing the file, storage eviction.
        // So: loud and named, but contained. Each is best-effort and re-runs on
        // the next boot, so there is nothing to retry here.
        const startupTask = (name: string, run: () => Promise<void>): void => {
            void run().catch((error) => {
                log.error(`post-bootstrap startup task failed (${name}) — it re-runs on the next boot:`, error);
            });
        };

        // Reconcile the app timezone against the device (story 169). In the
        // default "follow device" mode this persists the current device zone so
        // server-side reminders track the user's location while travelling.
        const appTimeZone = initAppTimeZone();
        startupTask('app timezone', () => appTimeZone);
        // Health targets (story 258): load the synced budget/protein/steps
        // rows and migrate the legacy localStorage calorie target once.
        const healthTargets = initHealthTargets();
        startupTask('health targets', () => healthTargets);
        startupTask('push subscription', () => notificationsService.ensurePushSubscription());
        // Story 359: push what earlier sessions queued — and the two settings
        // writes above, which every cold boot makes — once they have landed.
        startupTask('push queued changes', async () => {
            await Promise.allSettled([appTimeZone, healthTargets]);
            await syncQueuedChanges('startup');
            await shipQueuedPhotos('startup');
        });
        armAutoSync();

        // When a queued image upload finally ships, patch the corresponding
        // food/meal row's `image_path` in the local DB. The components hold
        // the pending sentinel UI-side only (so it never reaches the
        // server). The drain itself puts the path on the server's row
        // (story 362) — this listener only keeps the open replica in step.
        if (typeof BroadcastChannel !== 'undefined') {
            const uploadChannel = new BroadcastChannel(IMAGE_UPLOAD_SUCCESS_CHANNEL);
            uploadChannel.onmessage = async (e) => {
                const data = e.data;
                if (!data || data.type !== 'image-upload-success' || !data.image_path || !data.local_ref) return;
                try {
                    const driver = DbService.getInstance().driver;
                    if (data.scope === 'food') {
                        await driver.execute('UPDATE food_items SET image_path = ? WHERE id = ?', data.image_path, data.local_ref);
                    } else if (data.scope === 'meal') {
                        await driver.execute('UPDATE meals SET image_path = ? WHERE id = ?', data.image_path, data.local_ref);
                    }
                } catch (err) {
                    console.error('Failed to auto-update local db on image success broadcast:', err);
                }
            };
        }

        // Snapshot-freshness triggers 2 and 3 (story 133), now also the push
        // (story 359): queued offline changes go out first, then
        // `syncPendingChanges` ends with `refreshIfStale()`, which bails
        // cheaply if the server's generation hasn't moved.
        window.addEventListener('online', () => {
            void syncQueuedChanges('online').finally(() => shipQueuedPhotos('online'));
            void drainEstimateSubmits('online');
        });
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState !== 'visible') return;
            void syncQueuedChanges('visible');
            // Story 378: back from a trip — persist the device zone the server schedules by.
            void initAppTimeZone().catch((err) => console.warn('App time zone re-check failed:', err));
        });
        // Story 221: ship any async-estimate submits queued in a prior (possibly
        // offline) session — this is the "fires on next open" guarantee. Fails
        // fast and harmlessly when still offline; the entries stay queued.
        void drainEstimateSubmits('startup');
    });

    // After the home screen is shown, pre-load section entry points during
    // browser idle time so the first navigation to each section is instant.
    requestIdleCallback(() => {
        void import('./components/health/health-dashboard-screen/health-dashboard-screen.component.js');
        void import('./components/projects/projects-dashboard-screen/projects-dashboard-screen.component.js');
        void import('./components/vietnamese/vietnamese-dashboard-screen/vietnamese-dashboard-screen.component.js');
        void import('./components/goal/goals-screen/goals-screen.component.js');
        void import('./components/agenda/agenda-screen/agenda-screen.component.js');
    });
}
