import type { RouteConfig } from '../../router.js';
import { parseDayTab } from './health-day-tabs.js';
import type { HealthDashboardScreen } from './health-dashboard-screen/health-dashboard-screen.component.js';
import type { HealthDayScreen } from './health-day-screen/health-day-screen.component.js';
import type { HealthScannerScreen } from './health-scanner-screen/health-scanner-screen.component.js';
import type { HealthFoodEntryScreen } from './health-food-entry-screen/health-food-entry-screen.component.js';
import type { HealthAiEstimateScreen } from './health-ai-estimate-screen/health-ai-estimate-screen.component.js';
import type { HealthEstimateReviewScreen } from './health-estimate-review-screen/health-estimate-review-screen.component.js';
import type { HealthNutritionEditScreen } from './health-nutrition-edit-screen/health-nutrition-edit-screen.component.js';
import type { HealthActivityEditScreen } from './health-activity-edit-screen/health-activity-edit-screen.component.js';
import type { HealthMealsScreen } from './health-meals-screen/health-meals-screen.component.js';
import type { StrengthLoggingScreen } from './strength-logging-screen/strength-logging-screen.component.js';
import type { HealthExercisesScreen } from './health-exercises-screen/health-exercises-screen.component.js';
import type { HealthWorkoutTemplatesScreen } from './health-workout-templates-screen/health-workout-templates-screen.component.js';
import type { HealthCoachingScreen } from './health-coaching-screen/health-coaching-screen.component.js';
import type { HealthWeightScreen } from './health-weight-screen/health-weight-screen.component.js';

/**
 * Story 291: the add-food task — pick a food, scan it, estimate it, review the
 * estimate. `exitFlow()` pops every entry carrying this tag, so logging the
 * food leaves none of the steps on the back stack.
 */
const ADD_FOOD = 'add-food';

export function healthRoutes(): Record<string, RouteConfig> {
    return {
        '/health': {
            parent: '/',
            render: async () => {
                await import('./health-dashboard-screen/health-dashboard-screen.component.js');
                return document.createElement('health-dashboard-screen') as HealthDashboardScreen;
            },
        },
        '/health/scanner': {
            parent: '/health/food-entry',
            flow: ADD_FOOD,
            render: async (ctx) => {
                await import('./health-scanner-screen/health-scanner-screen.component.js');
                const screen = document.createElement('health-scanner-screen') as HealthScannerScreen;
                screen.query = ctx.query;
                return screen;
            },
        },
        '/health/scanner/:date/:meal': {
            parent: '/health/food-entry/:date/:meal',
            flow: ADD_FOOD,
            render: async (ctx) => {
                await import('./health-scanner-screen/health-scanner-screen.component.js');
                const screen = document.createElement('health-scanner-screen') as HealthScannerScreen;
                screen.date = decodeURIComponent(ctx.params.date);
                screen.meal = decodeURIComponent(ctx.params.meal);
                screen.query = ctx.query;
                return screen;
            },
        },
        '/health/food-entry': {
            parent: '/health',
            flow: ADD_FOOD,
            render: async (ctx) => {
                await import('./health-food-entry-screen/health-food-entry-screen.component.js');
                const screen = document.createElement('health-food-entry-screen') as HealthFoodEntryScreen;
                screen.query = ctx.query;
                return screen;
            },
        },
        '/health/food-entry/:date/:meal': {
            parent: '/health/day/:date',
            flow: ADD_FOOD,
            render: async (ctx) => {
                await import('./health-food-entry-screen/health-food-entry-screen.component.js');
                const screen = document.createElement('health-food-entry-screen') as HealthFoodEntryScreen;
                screen.date = decodeURIComponent(ctx.params.date);
                screen.meal = decodeURIComponent(ctx.params.meal);
                screen.query = ctx.query;
                return screen;
            },
        },
        '/health/ai-estimate': {
            parent: '/health/food-entry',
            flow: ADD_FOOD,
            render: async (ctx) => {
                await import('./health-ai-estimate-screen/health-ai-estimate-screen.component.js');
                const screen = document.createElement('health-ai-estimate-screen') as HealthAiEstimateScreen;
                screen.query = ctx.query;
                return screen;
            },
        },
        '/health/ai-estimate/:date/:meal': {
            parent: '/health/food-entry/:date/:meal',
            flow: ADD_FOOD,
            render: async (ctx) => {
                await import('./health-ai-estimate-screen/health-ai-estimate-screen.component.js');
                const screen = document.createElement('health-ai-estimate-screen') as HealthAiEstimateScreen;
                screen.date = decodeURIComponent(ctx.params.date);
                screen.meal = decodeURIComponent(ctx.params.meal);
                screen.query = ctx.query;
                return screen;
            },
        },
        // Story 211: async-estimate review (notification deep-link target).
        // Story 291: it is the last step of the add-food flow — that it was not
        // in the two hand-written prefix arrays is what left a logged estimate
        // sitting one back press away, still offering to log itself again.
        '/health/estimates/:id': {
            parent: '/health',
            flow: ADD_FOOD,
            render: async (ctx) => {
                await import('./health-estimate-review-screen/health-estimate-review-screen.component.js');
                const screen = document.createElement('health-estimate-review-screen') as HealthEstimateReviewScreen;
                screen.jobId = decodeURIComponent(ctx.params.id);
                // Story 221: the submit flow navigates here with a client_submit_id
                // (not yet a server job) + ?pending — the screen then resolves it
                // against the local submit queue. Notifications/deep-links carry a
                // real job id and skip that lookup.
                screen.pending = ctx.query.get('pending') === '1';
                return screen;
            },
        },
        '/health/day/:date': {
            parent: '/health',
            render: async (ctx) => {
                // Story 289: `?tab=activity` (the timeline's activity side, and
                // the return from an activity edit) opens the Activity half.
                // Validate before the import so a bogus value fails loud
                // through the router's route-error screen.
                const tab = parseDayTab(ctx.query.get('tab'));
                await import('./health-day-screen/health-day-screen.component.js');
                const screen = document.createElement('health-day-screen') as HealthDayScreen;
                screen.date = decodeURIComponent(ctx.params.date);
                screen.activeTab = tab;
                return screen;
            },
        },
        // The day is the true parent of both edit screens, but its `:date`
        // lives on the entry, not in the URL — so the rung is declared (it is
        // what makes the return animate as back) and drops out of any resolved
        // chain, leaving `/health`. The screens keep navigating to the concrete
        // day themselves on save, where they do know the date.
        '/health/nutrition/:id': {
            parent: '/health/day/:date',
            render: async (ctx) => {
                await import('./health-nutrition-edit-screen/health-nutrition-edit-screen.component.js');
                const screen = document.createElement('health-nutrition-edit-screen') as HealthNutritionEditScreen;
                screen.entryId = decodeURIComponent(ctx.params.id);
                return screen;
            },
        },
        '/health/activity/:id': {
            parent: '/health/day/:date',
            render: async (ctx) => {
                await import('./health-activity-edit-screen/health-activity-edit-screen.component.js');
                const screen = document.createElement('health-activity-edit-screen') as HealthActivityEditScreen;
                screen.entryId = decodeURIComponent(ctx.params.id);
                return screen;
            },
        },
        '/health/meals': {
            parent: '/health',
            render: async (ctx) => {
                await import('./health-meals-screen/health-meals-screen.component.js');
                const screen = document.createElement('health-meals-screen') as HealthMealsScreen;
                screen.query = ctx.query;
                return screen;
            },
        },
        // `:id`, not `:activityId`, so the declared parent below resolves from
        // the same param name the activity hub uses. The URL shape is
        // unchanged — only the pattern's placeholder is.
        '/health/workouts/:id': {
            parent: '/health/activity/:id',
            render: async (ctx) => {
                await import('./strength-logging-screen/strength-logging-screen.component.js');
                const screen = document.createElement('strength-logging-screen') as StrengthLoggingScreen;
                screen.activityId = decodeURIComponent(ctx.params.id);
                return screen;
            },
        },
        '/health/exercises': {
            parent: '/health',
            render: async () => {
                await import('./health-exercises-screen/health-exercises-screen.component.js');
                return document.createElement('health-exercises-screen') as HealthExercisesScreen;
            },
        },
        '/health/workout-templates': {
            parent: '/health',
            render: async () => {
                await import('./health-workout-templates-screen/health-workout-templates-screen.component.js');
                return document.createElement('health-workout-templates-screen') as HealthWorkoutTemplatesScreen;
            },
        },
        '/health/weight': {
            parent: '/health',
            render: async () => {
                await import('./health-weight-screen/health-weight-screen.component.js');
                return document.createElement('health-weight-screen') as HealthWeightScreen;
            },
        },
        '/health/coaching': {
            parent: '/health',
            render: async () => {
                await import('./health-coaching-screen/health-coaching-screen.component.js');
                return document.createElement('health-coaching-screen') as HealthCoachingScreen;
            },
        },
        // That day's briefing belongs to that day, so the chain runs through it.
        '/health/coaching/:date': {
            parent: '/health/day/:date',
            render: async (ctx) => {
                await import('./health-coaching-screen/health-coaching-screen.component.js');
                const screen = document.createElement('health-coaching-screen') as HealthCoachingScreen;
                screen.date = decodeURIComponent(ctx.params.date);
                return screen;
            },
        },
    };
}
