import type { RouteConfig } from '../../router.js';

export function goalRoutes(): Record<string, RouteConfig> {
    return {
        '/goals': {
            // Reached from the Extra screen's nav, not from home.
            parent: '/extra',
            render: async () => {
                await import('./goals-screen/goals-screen.component.js');
                return document.createElement('goals-screen');
            },
        },
    };
}
