import type { ApiResponse, RouteContext } from './response-helpers.js';

// --- Shared health API surface ---

/**
 * Every key in this union is a route that is implemented once in shared code
 * and consumed by both the Express server and the PWA offline router.
 *
 * Server-only routes (OpenFoodFacts proxy, AI estimation, calendar
 * activities) are NOT listed here — they are defined exclusively in
 * server/src/modules/sections/health/health.routes.ts.
 *
 * Story 116 — `/nutrition*` was renamed to `/consumption-entries*` and
 * `/food-library*` was renamed to `/food-items*` to mirror the new schema.
 */
export type HealthRouteKey =
    | 'GET /stats'
    | 'GET /activities'
    | 'GET /activities/:id'
    | 'POST /activities'
    | 'PATCH /activities/:id'
    | 'DELETE /activities/:id'
    | 'GET /consumption-entries/summary'
    | 'GET /consumption-entries'
    | 'GET /consumption-entries/:id'
    | 'POST /consumption-entries'
    | 'PATCH /consumption-entries/:id'
    | 'DELETE /consumption-entries/:id'
    // Logged-meal (occurrence group) bulk operations (story 255)
    | 'POST /consumption-entries/occurrence/:occurrenceId/scale'
    | 'PATCH /consumption-entries/occurrence/:occurrenceId'
    | 'DELETE /consumption-entries/occurrence/:occurrenceId'
    // Weight entries (story 170)
    | 'GET /weight-entries'
    | 'POST /weight-entries'
    | 'PATCH /weight-entries/:id'
    | 'DELETE /weight-entries/:id'
    // Daily steps (story 251)
    | 'GET /daily-steps'
    | 'PUT /daily-steps/:date'
    // Slot-scoped frequent-items grid, mixing foods and meals (story 276)
    | 'GET /frequent-entries'
    | 'GET /food-items/search'
    | 'GET /food-items/recent'
    | 'GET /food-items/frequent'
    | 'GET /food-items/barcode/:barcode'
    | 'GET /food-items/:id'
    | 'POST /food-items'
    | 'POST /food-items/:id/barcodes'
    | 'POST /food-items/log-new'
    | 'PATCH /food-items/:id'
    | 'POST /food-items/:id/log'
    | 'GET /meals'
    | 'GET /meals/search'
    | 'GET /meals/:id'
    | 'POST /meals'
    | 'PATCH /meals/:id'
    | 'DELETE /meals/:id'
    | 'POST /meals/:id/log'
    // Exercises (story 141)
    | 'GET /exercises'
    | 'GET /exercises/:id'
    | 'POST /exercises'
    | 'PATCH /exercises/:id'
    | 'POST /exercises/:id/archive'
    | 'POST /exercises/:id/unarchive'
    | 'GET /exercises/:id/recent-strength-sets'
    | 'GET /exercises/:id/previous-strength-sets'
    | 'GET /exercises/:id/max-strength-set'
    // Cardio details (1:1 subtype of activities)
    | 'GET /cardio-details/:activityId'
    | 'PATCH /cardio-details/:activityId'
    // Workout templates
    | 'GET /workout-templates'
    | 'GET /workout-templates/:id'
    | 'POST /workout-templates'
    | 'PATCH /workout-templates/:id'
    | 'POST /workout-templates/:id/archive'
    // Workout sessions
    | 'GET /workouts/:activityId'
    | 'POST /workouts'
    | 'PATCH /workouts/:activityId'
    | 'DELETE /workouts/:activityId'
    | 'POST /workouts/from-template/:templateId'
    // Strength sets (sub-resource of a workout session; created with parent context, edited by own id)
    | 'POST /workouts/:activityId/strength-sets'
    | 'PATCH /strength-sets/:id'
    | 'DELETE /strength-sets/:id'
    // Workout blocks (intervals / rest / notes)
    | 'POST /workouts/:activityId/workout-blocks'
    | 'PATCH /workout-blocks/:id'
    | 'DELETE /workout-blocks/:id';

/** Exhaustive TypeScript interface ensuring all routes are implemented. */
