/**
 * Registers the Service Worker and returns its registration.
 *
 * Story 306 — this used to await ACTIVATION, bounded by a 10 s timeout, and
 * reject when the worker was slower than that. Its one consumer was the
 * cross-origin-isolation halt in `app.ts`, which treated the rejection as "no
 * service worker" and abandoned the boot: a first install precaching ~120
 * assets over a weak radio is routinely slower than 10 s, and the app was left
 * on "Initializing Offline Storage" until it was force-quit, while the worker
 * activated seconds later with nobody listening. That halt now waits on
 * `navigator.serviceWorker.ready`, which cannot time out, so the bounded wait
 * here had no consumer left — only the ability to report a slow install as a
 * failure, which is a lie the console does not need.
 *
 * So this resolves once the worker is REGISTERED. "Is one active yet" is a
 * different question with a purpose-built answer (`ready`), and callers that
 * need it should ask that instead.
 */
async function registerServiceWorker({ scope = '/' } = {}) {
    if (!('serviceWorker' in navigator)) {
        throw new Error('Service Workers not supported');
    }

    if (import.meta.env.DEV) {
        return null;
    }

    const url = new URL(`${import.meta.env.BASE_URL}service-worker.js`, location.href);

    const registration = await navigator.serviceWorker.register(url, { scope, type: 'module' });
    if (registration.active) {
        // Story 232: a worker already controls the page, but `register()` alone
        // trusts the resident worker forever — a freshly deployed `service-worker.js`
        // (its import URLs change whenever app chunks change) would never install,
        // so the device stays pinned to the old build. Force a byte-check now.
        // `updateViaCache` defaults to 'imports', so the top-level SW script is
        // fetched bypassing the HTTP cache — exactly the check we want. The SW
        // self-`skipWaiting()`s + `clients.claim()`s, so any new worker activates
        // and `reloadOnServiceWorkerUpdate` swaps the page in. Fire-and-forget:
        // an offline/slow/rejected update must never block or fail boot.
        void registration.update().catch(() => { /* transient — next boot retries */ });
    }

    return registration;
}

// Unregister the Service Worker.
async function unregisterServiceWorker() {
    const registration = await navigator.serviceWorker.getRegistration();
    if (!registration) {
        throw new Error('No Service Worker registered');
    }
    return registration.unregister();
}

/**
 * Story 232: when a newly-activated service worker takes control of this page
 * (the `controllerchange` that follows the SW's `skipWaiting()` + `clients.claim()`
 * after a deploy), reload once into the fresh build — so a live deploy stops being
 * invisible until a manual hard-reload / app kill.
 *
 * Gated on a controller being present *now*: a controller swap means an update,
 * whereas first-ever control acquisition (no prior controller) is the COI
 * bootstrap's reload to own (`app.ts`) — auto-reloading there would double-reload
 * and could loop. The one-shot `reloading` guard caps it at a single reload per
 * page lifetime. Attach this BEFORE `registerServiceWorker()` so no swap is missed.
 *
 * Injectable `container` / `reload` for unit testing; defaults to the real ones.
 * Inert with no container (unsupported / DEV, where no SW is registered).
 */
function reloadOnServiceWorkerUpdate(
    container: ServiceWorkerContainer | undefined = typeof navigator !== 'undefined' ? navigator.serviceWorker : undefined,
    reload: () => void = () => { window.location.reload(); },
): void {
    if (!container || !container.controller) {
        return;
    }
    let reloading = false;
    container.addEventListener('controllerchange', () => {
        if (reloading) return;
        reloading = true;
        reload();
    });
}

export { registerServiceWorker, unregisterServiceWorker, reloadOnServiceWorkerUpdate };
