/**
 * Story 252 — the shared "counts as a meaningful activity" predicate.
 *
 * Health Connect ingests every Fit auto-detected walk (story 250 keeps them
 * all at ingest), which would trivialise the activity streak and clutter the
 * timeline. Display-side, a walk is hidden only when it is positively tiny:
 * under BOTH the distance and duration bars (owner: "keep it LOW — hide only
 * the tiniest walks"). A missing metric keeps the walk visible — absence of
 * evidence is not evidence of a stroll.
 *
 * Used by the streak (`GET /stats`) and overview reads
 * (`GET /activities?filter=meaningful`); the day-detail drill-in still shows
 * everything.
 */

export const TRIVIAL_WALK_MAX_DISTANCE_M = 500;
export const TRIVIAL_WALK_MAX_DURATION_MIN = 10;

export interface ActivitySignal {
    type: string;
    duration_minutes?: number | null;
    distance_m?: number | null;
}

export function isTrivialWalk(signal: ActivitySignal): boolean {
    if (signal.type !== 'walking') return false;
    const durationUnderBar = signal.duration_minutes != null && signal.duration_minutes < TRIVIAL_WALK_MAX_DURATION_MIN;
    const distanceUnderBar = signal.distance_m != null && signal.distance_m < TRIVIAL_WALK_MAX_DISTANCE_M;
    return durationUnderBar && distanceUnderBar;
}
