    async 'POST /meals/:id/log'({ params, body: requestBody }: RouteContext): Promise<ApiResponse> {
        const { id } = params;
        if (!id) return this.badRequest('Invalid id');
        const b = (requestBody ?? {}) as {
            date?: string;
            meal_type?: MealType;
            scale?: number;
            consumed_at?: string;
            ingredients?: Array<{ food_item_id?: unknown; amount?: unknown }>;
        };
        if (!b.date) return this.badRequest('date is required');
        const badDate = this.invalidDate(b.date);
        if (badDate) return badDate;
        if (!b.meal_type) return this.badRequest('meal_type is required');
        if (!MEAL_TYPES.includes(b.meal_type)) {
            return this.badRequest(`meal_type must be one of: ${MEAL_TYPES.join(', ')}`);
        }
        if (b.scale !== undefined && (typeof b.scale !== 'number' || !Number.isFinite(b.scale) || b.scale <= 0)) {
            return this.badRequest('scale must be a positive number');
        }
        // Story 311: the per-occurrence ingredient list. Shaped here so a bad
        // payload is a 400 naming the offending line rather than a repository
        // throw surfacing as a 500.
        let ingredients: Array<{ food_item_id: string; amount: number }> | undefined;
        if (b.ingredients !== undefined) {
            if (!Array.isArray(b.ingredients) || b.ingredients.length === 0) {
                return this.badRequest('ingredients must be a non-empty array');
            }
            if (b.scale !== undefined) {
                return this.badRequest('provide either ingredients or scale, not both — an explicit list already carries final amounts');
            }
            const seen = new Set<string>();
            ingredients = [];
            for (const [i, line] of b.ingredients.entries()) {
                if (!line || typeof line !== 'object') return this.badRequest(`ingredients[${i}] must be an object`);
                if (!line.food_item_id || typeof line.food_item_id !== 'string') {
                    return this.badRequest(`ingredients[${i}].food_item_id is required`);
                }
                if (typeof line.amount !== 'number' || !Number.isFinite(line.amount) || line.amount <= 0) {
                    return this.badRequest(`ingredients[${i}].amount must be a positive number`);
                }
                if (seen.has(line.food_item_id)) {
                    return this.badRequest(`ingredients[${i}] repeats food_item_id ${line.food_item_id} — one amount per food`);
                }
                seen.add(line.food_item_id);
                ingredients.push({ food_item_id: line.food_item_id, amount: line.amount });
            }
        }
        const consumedAt = b.consumed_at != null ? normalizeIsoInstant(b.consumed_at) ?? undefined : undefined;
        if (b.consumed_at != null && !consumedAt) {
            return this.badRequest('consumed_at must be an ISO instant (offset or Z required)');
        }
        const result = await this.repos.meals.logMeal(id, {
            date: b.date,
            meal_type: b.meal_type,
            scale: b.scale,
            consumed_at: consumedAt,
            ingredients,
        });
        return this.created(result);
    }

