    private validateExercisePayload(b: Partial<NewExercise>, { requireCore }: { requireCore: boolean }): ApiResponse | null {
        if (requireCore || b.canonical_name !== undefined) {
            if (!b.canonical_name || !b.canonical_name.trim()) return this.badRequest('canonical_name is required');
        }
        if (requireCore || b.display_name !== undefined) {
            if (!b.display_name || !b.display_name.trim()) return this.badRequest('display_name is required');
        }
        if (b.category !== undefined && !EXERCISE_CATEGORIES.includes(b.category as ExerciseCategory)) {
            return this.badRequest(`category must be one of: ${EXERCISE_CATEGORIES.join(', ')}`);
        }
        if (b.default_unit !== undefined && !EXERCISE_DEFAULT_UNITS.includes(b.default_unit as ExerciseDefaultUnit)) {
            return this.badRequest(`default_unit must be one of: ${EXERCISE_DEFAULT_UNITS.join(', ')}`);
        }
        // Story 288 — the column is NOT NULL and the card's toggle is binary;
        // anything else would land as a silent truthy value in SQLite.
        if (b.is_unilateral !== undefined && b.is_unilateral !== 0 && b.is_unilateral !== 1) {
            return this.badRequest('is_unilateral must be 0 or 1');
        }
        return null;
    }

