import type { RouteConfig } from '../../router.js';

/**
 * Story 381 (pwa-shell-21): each route imports its own screen, per DL #82 — a memoized batch let
 * one failed chunk fail both routes until a reload.
 */
export function vietnameseRoutes(): Record<string, RouteConfig> {
    return {
        '/vietnamese': {
            parent: '/',
            render: async () => {
                await import('./vietnamese-dashboard-screen/vietnamese-dashboard-screen.component.js');
                return document.createElement('vietnamese-dashboard-screen');
            },
        },
        '/vietnamese/review': {
            parent: '/vietnamese',
            render: async () => {
                await import('./vietnamese-review-screen/vietnamese-review-screen.component.js');
                return document.createElement('vietnamese-review-screen');
            },
        },
    };
}
