import type { RouteConfig } from '../../router.js';

export function statusScreenRoutes(): Record<string, RouteConfig> {
    return {
        '/status': {
            // Reached from the sync-status pill in the home footer.
            parent: '/',
            // Story 381 (pwa-shell-22): lazy like every other route (DL #82) — it was the only one
            // imported up front, so its sections and the HC sync panel loaded before home's first paint.
            render: async () => {
                await import('./status-screen.component.js');
                return document.createElement('status-screen');
            },
        },
    };
}
