import { BadRequestError } from './response-helpers.js';

export function isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Story 389 — the one `?limit=` reader. Absent or empty means the route's default; anything but a
 * positive integer is a 400, never a silent default (`?limit=-1` returned the whole library).
 */
export function parseLimit(query: URLSearchParams, fallback: number): number {
    const raw = query.get('limit');
    if (raw === null || raw === '') return fallback;
    const limit = Number(raw);
    if (!Number.isInteger(limit) || limit <= 0) {
        throw new BadRequestError(`limit must be a positive integer, got "${raw}"`);
    }
    return limit;
}

export function parseNonEmptyString(value: unknown): string | null {
    if (typeof value !== 'string') {
        return null;
    }
    const normalized = value.trim();
    return normalized.length > 0 ? normalized : null;
}

export function parseOptionalNonEmptyString(value: unknown): string | undefined {
    if (typeof value !== 'string') {
        return undefined;
    }
    const normalized = value.trim();
    return normalized.length > 0 ? normalized : undefined;
}

/** NUL and the C0 controls other than tab, LF and CR, plus DEL. */
export const FORBIDDEN_CONTROL_CHAR_RE = /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/;

export type FreeTextResult =
    | { valid: true; value: string | undefined }
    | { valid: false; error: 'missing' | 'not-text' | 'control-character' };

/**
 * The one free-text policy (story 379, DLR #301). Text is kept as typed — newlines, tabs, '<' and
 * '>' included; rendering escapes it (story 014's textContent rule) — and trimmed at the ends. A
 * control character is rejected, never stripped: a stripped value silently differs from what was
 * sent. Blank counts as absent.
 */
export function parseFreeText(value: unknown, { required }: { required: boolean }): FreeTextResult {
    if (value === undefined || value === null) {
        return required ? { valid: false, error: 'missing' } : { valid: true, value: undefined };
    }
    if (typeof value !== 'string') return { valid: false, error: 'not-text' };
    if (FORBIDDEN_CONTROL_CHAR_RE.test(value)) return { valid: false, error: 'control-character' };
    const trimmed = value.trim();
    if (trimmed.length === 0) {
        return required ? { valid: false, error: 'missing' } : { valid: true, value: undefined };
    }
    return { valid: true, value: trimmed };
}
