import type { Activity, ActivityWithDistance, NewActivity } from '../index.js';
import type { DbDriver } from '../types/db.js';
import { NOOP_LOGGER, type RepoLogger } from '../types/logger.js';
import { uuidv7 } from '../utils/uuid.js';
import { ConflictError, NotFoundError } from '../api/response-helpers.js';
import { nowTimestamp } from '../utils/timestamp.js';

export interface HealthRepositoryOptions {
    log?: RepoLogger;
}

/**
 * Story 265 — SQLite's own errmsg for the partial unique index on
 * `activities.external_id` (`idx_activities_external_id`). Identical text under
 * `node:sqlite` and `sqlite-wasm`, so matching the message is the one check
 * that works in both runtimes this repository serves.
 *
 * Deliberately NARROW: only this constraint becomes a 409. Any other UNIQUE
 * violation (a UUIDv7 primary-key collision, another table) is a real bug and
 * must keep escaping as an unhandled 500 — see development_principles.md
 * §Core Philosophy, "Fail Loudly & Visibly".
 */
const DUPLICATE_EXTERNAL_ID_ERRMSG = 'UNIQUE constraint failed: activities.external_id';

const isDuplicateExternalId = (err: unknown): boolean =>
    err instanceof Error && err.message.includes(DUPLICATE_EXTERNAL_ID_ERRMSG);

export function createHealthRepository(driver: DbDriver, options: HealthRepositoryOptions = {}) {
    const log = options.log ?? NOOP_LOGGER;
    const repository = {
        async getAllActivities(limit = 50): Promise<Activity[]> {
            log.debug('health.getAllActivities', { limit });
            return driver.query<Activity>('SELECT * FROM activities ORDER BY date DESC LIMIT ?', limit);
        },

        async findActivityById(id: string): Promise<Activity | null> {
            log.debug('health.findActivityById', { id });
            return driver.queryOne<Activity>('SELECT * FROM activities WHERE id = ?', [id]);
        },

        async getActivityById(id: string): Promise<Activity> {
            log.debug('health.getActivityById', { id });
            return driver.queryOne<Activity>('SELECT * FROM activities WHERE id = ?', [id], {
                notFound: () => new NotFoundError(`Activity ${id} not found`),
            });
        },

        // Activity reads join the cardio distance (story 259 follow-up): the
        // meaningful filter needs it for isTrivialWalk, and burn estimates
        // pace-band walking/running/cycling with it — one query, no N+1.
        // Story 312 adds `moving_time_minutes` to the same join, which is what
        // lets the step estimate and the run's own pace be derived on read
        // instead of stored. `getActivitySignalsSince` below deliberately does
        // NOT take it: it selects an explicit column list for `isTrivialWalk`,
        // which asks about distance and duration only.
        async getActivitiesByDateRange(from: string, to: string): Promise<ActivityWithDistance[]> {
            log.debug('health.getActivitiesByDateRange', { from, to });
            return driver.query<ActivityWithDistance>(
                `SELECT a.*, cd.distance_m, cd.moving_time_minutes
                FROM activities a
                LEFT JOIN cardio_details cd ON cd.activity_id = a.id
                WHERE a.date >= ? AND a.date <= ?
                ORDER BY a.date DESC`,
                from,
                to,
            );
        },

        async getActivitiesByDate(date: string): Promise<ActivityWithDistance[]> {
            log.debug('health.getActivitiesByDate', { date });
            return driver.query<ActivityWithDistance>(
                `SELECT a.*, cd.distance_m, cd.moving_time_minutes
                FROM activities a
                LEFT JOIN cardio_details cd ON cd.activity_id = a.id
                WHERE a.date = ?
                ORDER BY a.date DESC`,
                date,
            );
        },

        /**
         * Per-activity streak signals (story 252): date + the fields the shared
         * `isTrivialWalk` predicate needs, so the stats route can exclude
         * trivial walks from the streak without a second query.
         */
        async getActivitySignalsSince(sinceDate: string): Promise<Array<{ date: string; type: string; duration_minutes: number | null; distance_m: number | null }>> {
            log.debug('health.getActivitySignalsSince', { sinceDate });
            return driver.query(
                `SELECT a.date, a.type, a.duration_minutes, cd.distance_m
                FROM activities a
                LEFT JOIN cardio_details cd ON cd.activity_id = a.id
                WHERE a.date >= ?
                ORDER BY a.date DESC`,
                sinceDate,
            );
        },

        async findActivityByExternalId(externalId: string): Promise<Activity | null> {
            log.debug('health.findActivityByExternalId', { externalId });
            return driver.queryOne<Activity>('SELECT * FROM activities WHERE external_id = ?', [externalId]);
        },

        async createActivity(activity: NewActivity): Promise<Activity> {
            const id = uuidv7();
            log.debug('health.createActivity', { id, type: activity.type, source: activity.source });
            try {
                await driver.execute(
                    `
                        INSERT INTO activities (id, type, source, title, description, date, duration_minutes, calories_burned, external_id, metadata)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    `,
                    id,
                    activity.type,
                    activity.source,
                    activity.title,
                    activity.description ?? null,
                    activity.date,
                    activity.duration_minutes ?? null,
                    activity.calories_burned ?? null,
                    activity.external_id ?? null,
                    activity.metadata ?? null,
                );
            } catch (err) {
                // Re-ingesting an already-synced source record is a conflict, not
                // a server fault: the adapters map ConflictError to 409 + JSON so
                // the caller can read the reason instead of an HTML 500 page.
                if (isDuplicateExternalId(err)) {
                    log.warn('health.createActivity duplicate external_id', { external_id: activity.external_id });
                    throw new ConflictError(`Activity with external_id "${activity.external_id}" already exists`);
                }
                throw err;
            }
            return driver.queryOne<Activity>('SELECT * FROM activities WHERE id = ?', [id], {
                notFound: () => new Error(`Failed to load created activity: ${id}`),
            });
        },

        async updateActivity(id: string, updates: Partial<NewActivity>): Promise<Activity> {
            const existing = await repository.getActivityById(id);
            log.debug('health.updateActivity', { id, fields: Object.keys(updates) });

            const fields: string[] = [];
            const values: unknown[] = [];

            // `source`, `external_id` and `metadata` are here for the Health Connect re-ingest
            // (story 300's in-place upgrade): when HC reassigns a record id, the stored row has to
            // start pointing at the new one, or the next sync sees an unknown external_id, upgrades
            // again, and never converges. They were silently dropped before — the UPDATE ran, said
            // it succeeded, and left the row on the old id. Authorization for these lives in the
            // route guard (`PATCH /activities/:id`), which is the layer that knows the caller.
            const allowedFields = ['type', 'title', 'description', 'date', 'duration_minutes', 'calories_burned', 'source', 'external_id', 'metadata'] as const;
            for (const field of allowedFields) {
                if (updates[field] !== undefined) {
                    fields.push(`${field} = ?`);
                    values.push(updates[field] ?? null);
                }
            }

            if (fields.length === 0) return existing;

            // Story 374 (principles-02): the Health Connect write-back publishes `updated_at` as the
            // record version (story 299) — an edit that left it alone could never supersede the
            // published record.
            fields.push('updated_at = ?');
            values.push(nowTimestamp(), id);
            await driver.execute(`UPDATE activities SET ${fields.join(', ')} WHERE id = ?`, ...values);
            return repository.getActivityById(id);
        },

        async deleteActivity(id: string): Promise<boolean> {
            log.debug('health.deleteActivity', { id });
            const result = await driver.execute('DELETE FROM activities WHERE id = ?', id);
            return result.changes > 0;
        },
    };

    return repository;
}

export type HealthRepository = ReturnType<typeof createHealthRepository>;
