import type { RouteConfig } from '../../router.js';

/**
 * Story 381 (pwa-shell-21): each route imports its own screen, per DL #82. They used to await all
 * six through one memoized Promise.all, so one chunk that failed to load failed the whole section,
 * and the rejected promise stayed cached until a reload.
 */
export function projectsRoutes(): Record<string, RouteConfig> {
    return {
        '/projects': {
            parent: '/',
            render: async () => {
                await import('./projects-dashboard-screen/projects-dashboard-screen.component.js');
                return document.createElement('projects-dashboard-screen');
            },
        },
        '/projects/scrumboard': {
            parent: '/projects',
            render: async () => {
                await import('./projects-scrumboard-screen/projects-scrumboard-screen.component.js');
                return document.createElement('projects-scrumboard-screen');
            },
        },
        '/projects/stories': {
            parent: '/projects',
            render: async () => {
                await import('./projects-stories-screen/projects-stories-screen.component.js');
                return document.createElement('projects-stories-screen');
            },
        },
        '/projects/git-log': {
            parent: '/projects',
            render: async () => {
                await import('./projects-git-log-screen/projects-git-log-screen.component.js');
                return document.createElement('projects-git-log-screen');
            },
        },
        '/projects/logs': {
            parent: '/projects',
            render: async () => {
                await import('./projects-logs-screen/projects-logs-screen.component.js');
                return document.createElement('projects-logs-screen');
            },
        },
        '/projects/logs/client': {
            // A sibling of the server-log screen, not a child: the dashboard
            // links to both directly.
            parent: '/projects',
            render: async () => {
                await import('./projects-client-logs-screen/projects-client-logs-screen.component.js');
                return document.createElement('projects-client-logs-screen');
            },
        },
    };
}
