import { buildSectionPage } from '../../utils/section-page.utils.js';
import type { RouteConfig } from '../../router.js';

export function aiRoutes(): Record<string, RouteConfig> {
    return {
        '/ai': {
            parent: '/',
            render: async () => {
                await import('./local-ai-switch/local-ai-switch.component.js');
                const container = document.createElement('div');
                container.className = 'view-section';
                container.id = 'ai-view';
                const page = buildSectionPage(container, 'AI', 'ai', '/ai');
                page.content.appendChild(document.createElement('local-ai-switch'));
                return container;
            },
        },
    };
}
